INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('e6347282-3074-5302-bd63-c5f208cd6328','a0000000-0000-4000-8000-000000000001','Блок 1. The Indefinite Article a – an',1,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('680542fe-8630-5c92-9af4-b7bdd82432e2','e6347282-3074-5302-bd63-c5f208cd6328','The Indefinite Article a – an',0,'LESSON',70,$j$[{"type": "rule", "text": "We use 'an' before words which begin with a vowel (a, e, i, o, u). (Используем 'an' перед словами, начинающимися с гласной.)"}, {"type": "examples", "items": ["an atlas", "an eraser", "an orange"]}, {"type": "rule", "text": "We use 'a' before words that begin with a consonant. (Используем 'a' перед словами, начинающимися с согласной.)"}, {"type": "examples", "items": ["a notebook", "a pen", "a ruler"]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('da7bbc2c-c8df-5f32-8c35-a9d4c260eb3a','680542fe-8630-5c92-9af4-b7bdd82432e2',0,'FILL_BLANK','Вставь a или an.',$j${"items": [{"before": "", "after": "flag"}, {"before": "", "after": "dog"}, {"before": "", "after": "elephant"}, {"before": "", "after": "umbrella"}, {"before": "", "after": "clown"}, {"before": "", "after": "butterfly"}, {"before": "", "after": "ice cream"}]}$j$::jsonb,10);
