INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('070a406d-7e41-5bf6-8caa-1a999f85da29','680542fe-8630-5c92-9af4-b7bdd82432e2',1,'SORT_COLUMNS','Распредели слова по колонкам A / An.',$j${"columns": [{"id": "c1", "label": "A"}, {"id": "c2", "label": "An"}], "items": [{"id": "i1", "label": "apple"}, {"id": "i2", "label": "football"}, {"id": "i3", "label": "notebook"}, {"id": "i4", "label": "atlas"}, {"id": "i5", "label": "umbrella"}, {"id": "i6", "label": "pencil"}, {"id": "i7", "label": "book"}, {"id": "i8", "label": "eraser"}]}$j$::jsonb,10);
