INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('1c9f8db5-cc3d-5148-87b4-d48eeca1dea8','a0000000-0000-4000-8000-000000000001','Блок 2. Personal Subject Pronouns / Object Pronouns',2,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('c295fc66-252f-554e-8993-00287583f950','1c9f8db5-cc3d-5148-87b4-d48eeca1dea8','Personal Subject Pronouns / Object Pronouns',0,'LESSON',70,$j$[{"type": "text", "text": "Subject Pronouns (местоимения-подлежащие): Singular — I, you, he, she, it; Plural — we, you, they."}, {"type": "rule", "text": "I → always with a capital letter."}, {"type": "rule", "text": "he → for a man or a boy; she → for a woman or a girl; it → for an animal or a thing."}, {"type": "rule", "text": "we → for people; they → for people, animals or things."}, {"type": "text", "text": "Object Pronouns (местоимения-дополнения): Singular — me, you, him, her, it; Plural — us, you, them."}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('e3ee62ce-4483-5c0d-a87e-e19c3f8988bd','c295fc66-252f-554e-8993-00287583f950',0,'FILL_BLANK','Вставь правильное личное местоимение-подлежащее.',$j${"items": [{"before": "(two boys) →", "after": ""}, {"before": "(a teddy bear) →", "after": ""}, {"before": "(a girl) →", "after": ""}, {"before": "(a bird) →", "after": ""}, {"before": "(balloons) →", "after": ""}, {"before": "(a boy) →", "after": ""}, {"before": "(a man and a girl) →", "after": ""}]}$j$::jsonb,10);
