INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('f453e95c-d35d-51a5-80ef-51f65d6c3550','c295fc66-252f-554e-8993-00287583f950',1,'CHOOSE','Выбери правильное местоимение (subject/object).',$j${"items": [{"before": "This is my umbrella.", "after": "is red.", "options": [{"id": "o1", "label": "I"}, {"id": "o2", "label": "It"}]}, {"before": "This is Peter.", "after": "is fourteen.", "options": [{"id": "o1", "label": "She"}, {"id": "o2", "label": "He"}]}, {"before": "This is Laura and Rose.", "after": "are my friends.", "options": [{"id": "o1", "label": "They"}, {"id": "o2", "label": "She"}]}, {"before": "This is Tom and I'm Steven. Look at", "after": ".", "options": [{"id": "o1", "label": "us"}, {"id": "o2", "label": "them"}]}, {"before": "This is Rex and Spot.", "after": "are my dogs.", "options": [{"id": "o1", "label": "It"}, {"id": "o2", "label": "They"}]}, {"before": "Look at", "after": ". She's Kathy.", "options": [{"id": "o1", "label": "she"}, {"id": "o2", "label": "her"}]}, {"before": "This is my notebook.", "after": "is blue.", "options": [{"id": "o1", "label": "It"}, {"id": "o2", "label": "They"}]}, {"before": "This is Tony. Come and meet", "after": ".", "options": [{"id": "o1", "label": "he"}, {"id": "o2", "label": "him"}]}]}$j$::jsonb,10);
