INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('081cf4d3-cdb8-596f-9ac6-1e207ce44b35','a0000000-0000-4000-8000-000000000001','Блок 3. The verb ''to be''',3,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('55c9713c-3191-5ecf-8dd8-ab2e1f8abe07','081cf4d3-cdb8-596f-9ac6-1e207ce44b35','The verb ''to be''',0,'LESSON',70,$j$[{"type": "text", "text": "Long Form: I am, you are, he is, she is, it is, we are, you are, they are."}, {"type": "text", "text": "Short Form: I'm, you're, he's, she's, it's, we're, you're, they're."}, {"type": "text", "text": "Negative: I'm not, you aren't, he isn't, she isn't, it isn't, we aren't, they aren't."}, {"type": "text", "text": "Interrogative: Am I...? Are you...? Is he/she/it...? Are we/you/they...?"}, {"type": "rule", "text": "In short answers we do not repeat the whole question. We use the long form in positive short answers (Yes, she is.) and the short form in negative short answers (No, I'm not.)."}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('6ad91bad-e628-5494-a7de-be4a7df1d419','55c9713c-3191-5ecf-8dd8-ab2e1f8abe07',0,'FILL_BLANK','Вставь глагол to be: am, is или are.',$j${"items": [{"before": "I", "after": "twelve."}, {"before": "You", "after": "my friend."}, {"before": "It", "after": "a pencil."}, {"before": "They", "after": "brothers."}, {"before": "We", "after": "twins."}, {"before": "He", "after": "Paul."}, {"before": "She", "after": "from England."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('6ad91bad-e628-5494-a7de-be4a7df1d419',$j${"items": [{"accept": ["am", "'m", "m"]}, {"accept": ["are", "'re", "re"]}, {"accept": ["is", "'s", "s"]}, {"accept": ["are", "'re", "re"]}, {"accept": ["are", "'re", "re"]}, {"accept": ["is", "'s", "s"]}, {"accept": ["is", "'s", "s"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('ee9f54db-af9c-5714-8f5c-59000c9e343b','55c9713c-3191-5ecf-8dd8-ab2e1f8abe07',1,'FILL_BLANK','Дополни текст словами is, am или are.',$j${"items": [{"before": "Hi! My name", "after": "Rita."}, {"before": "I", "after": "eleven years old"}, {"before": "and I", "after": "from the UK."}, {"before": "I", "after": "a student at Newcastle Secondary School."}, {"before": "My favourite subjects", "after": "Geography and Music."}, {"before": "My favourite colour", "after": "pink"}, {"before": "and my favourite day", "after": "Saturday."}, {"before": "Helen and Sophie", "after": "my best friends."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('ee9f54db-af9c-5714-8f5c-59000c9e343b',$j${"items": [{"accept": ["is", "'s"]}, {"accept": ["am", "'m"]}, {"accept": ["am", "'m"]}, {"accept": ["am", "'m"]}, {"accept": ["are", "'re"]}, {"accept": ["is", "'s"]}, {"accept": ["is", "'s"]}, {"accept": ["are", "'re"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('ea2a7da4-25f5-50ca-af02-817202183585','55c9713c-3191-5ecf-8dd8-ab2e1f8abe07',2,'CHOOSE','Выбери правильную форму глагола to be.',$j${"items": [{"before": "I'm from Ireland. I", "after": "from England.", "options": [{"id": "o1", "label": "'m not"}, {"id": "o2", "label": "isn't"}]}, {"before": "We", "after": "in Grade 6.", "options": [{"id": "o1", "label": "isn't"}, {"id": "o2", "label": "aren't"}]}, {"before": "'Are Philip and Helen teachers?' 'Yes, they", "after": ".'", "options": [{"id": "o1", "label": "are"}, {"id": "o2", "label": "is"}]}, {"before": "He", "after": "my brother.", "options": [{"id": "o1", "label": "aren't"}, {"id": "o2", "label": "isn't"}]}, {"before": "They", "after": "my best friends.", "options": [{"id": "o1", "label": "'re"}, {"id": "o2", "label": "'s"}]}, {"before": "", "after": "they in your class?", "options": [{"id": "o1", "label": "Are"}, {"id": "o2", "label": "Is"}]}, {"before": "", "after": "she from Canada?", "options": [{"id": "o1", "label": "Is"}, {"id": "o2", "label": "Are"}]}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('ea2a7da4-25f5-50ca-af02-817202183585',$j${"items": [{"correctId": "o1"}, {"correctId": "o2"}, {"correctId": "o1"}, {"correctId": "o2"}, {"correctId": "o1"}, {"correctId": "o1"}, {"correctId": "o1"}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('081b2b8e-bdbd-5133-aa03-1e497c68b608','55c9713c-3191-5ecf-8dd8-ab2e1f8abe07',3,'MATCH_PAIRS','Соедини вопросы с ответами.',$j${"left": [{"id": "l1", "label": "Are they students?"}, {"id": "l2", "label": "Is Tom from the UK?"}, {"id": "l3", "label": "Is Mary nineteen years old?"}, {"id": "l4", "label": "Are you a teacher?"}, {"id": "l5", "label": "Are we in class 2E?"}], "right": [{"id": "r1", "label": "Yes, she is."}, {"id": "r2", "label": "No, they aren't."}, {"id": "r3", "label": "No, he isn't."}, {"id": "r4", "label": "Yes, we are."}, {"id": "r5", "label": "No, I'm not."}]}$j$::jsonb,10);
