INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('aeb35ca0-eba9-5027-8d21-3d8f8d5a17f7','a0000000-0000-4000-8000-000000000001','Блок 4. The verb ''have got''',4,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('7e7e10c8-43d7-5694-bee0-9131162f8f91','aeb35ca0-eba9-5027-8d21-3d8f8d5a17f7','The verb ''have got''',0,'LESSON',70,$j$[{"type": "rule", "text": "We use 'have got' to show that something belongs to somebody, to describe characteristics of people/animals/things, and to talk about relationships."}, {"type": "text", "text": "Affirmative: I/you/we/they have got ('ve got); he/she/it has got ('s got)."}, {"type": "text", "text": "Negative: haven't got; hasn't got. Interrogative: Have you got? Has he got?"}, {"type": "rule", "text": "In short answers we do not use 'got': Yes, I have. / No, he hasn't."}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('373c89e4-51d7-5d2f-9529-c8f3b91756e0','7e7e10c8-43d7-5694-bee0-9131162f8f91',0,'FILL_BLANK','Вставь have, haven''t, has или hasn''t.',$j${"items": [{"before": "", "after": "Ken got green eyes?"}, {"before": "No, he", "after": "."}, {"before": "We", "after": "got a red car. We've got a blue one."}, {"before": "", "after": "you got many friends?"}, {"before": "Yes, I", "after": "."}, {"before": "", "after": "they got a dog?"}, {"before": "No, they", "after": "."}, {"before": "I", "after": "got blue eyes. I've got green eyes."}, {"before": "", "after": "Aunt Betty got an umbrella?"}, {"before": "Yes, she", "after": "."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('373c89e4-51d7-5d2f-9529-c8f3b91756e0',$j${"items": [{"accept": ["has"]}, {"accept": ["hasn't", "has not"]}, {"accept": ["haven't", "have not"]}, {"accept": ["have"]}, {"accept": ["have"]}, {"accept": ["have"]}, {"accept": ["haven't", "have not"]}, {"accept": ["haven't", "have not"]}, {"accept": ["has"]}, {"accept": ["has"]}]}$j$::jsonb,'');
