INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('d51d171d-a91e-540a-83c6-9531804a302c','a0000000-0000-4000-8000-000000000001','Блок 5. Plurals',5,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('983972e0-58f5-5c36-b621-1347b073ba41','d51d171d-a91e-540a-83c6-9531804a302c','Plurals',0,'LESSON',70,$j$[{"type": "rule", "text": "Most nouns take -s to form the plural."}, {"type": "examples", "items": ["camera – cameras", "shoe – shoes"]}, {"type": "rule", "text": "Nouns ending in -s, -ss, -sh, -ch, -x, -o take -es."}, {"type": "examples", "items": ["bus – buses", "glass – glasses", "brush – brushes", "fox – foxes", "tomato – tomatoes"]}, {"type": "rule", "text": "Consonant + y drops -y and takes -ies (lady – ladies). Vowel + y takes -s (boy – boys)."}, {"type": "rule", "text": "Nouns ending in -f/-fe drop it and take -ves (scarf – scarves, life – lives)."}, {"type": "text", "text": "Irregular: man – men, woman – women, child – children, foot – feet, tooth – teeth, mouse – mice, person – people."}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('b5365a56-4708-54e3-af5c-1bbfd0fbe10a','983972e0-58f5-5c36-b621-1347b073ba41',0,'FILL_BLANK','Напиши форму множественного числа.',$j${"items": [{"before": "fly →", "after": ""}, {"before": "tomato →", "after": ""}, {"before": "foot →", "after": ""}, {"before": "mouse →", "after": ""}, {"before": "box →", "after": ""}, {"before": "tooth →", "after": ""}, {"before": "child →", "after": ""}, {"before": "glove →", "after": ""}]}$j$::jsonb,10);
