INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('08dda9a8-acce-5069-b68a-6e8ff0bdb792','a0000000-0000-4000-8000-000000000001','Блок 6. This / These – That / Those',6,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('f1b4cec2-1f66-5cda-9d21-05ae124e25af','08dda9a8-acce-5069-b68a-6e8ff0bdb792','This / These – That / Those',0,'LESSON',70,$j$[{"type": "rule", "text": "We use this (singular) / these (plural) to point to people, things and animals near us."}, {"type": "examples", "items": ["This is a chair.", "These are chairs."]}, {"type": "rule", "text": "We use that (singular) / those (plural) to point to people, things or animals far away."}, {"type": "examples", "items": ["That is a chair.", "Those are chairs."]}, {"type": "rule", "text": "We answer questions with 'it' or 'they': What's this? It's a pencil. What are these? They are pencils."}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('ee8f1441-1fac-58d7-b1a2-8f324acb529e','f1b4cec2-1f66-5cda-9d21-05ae124e25af',0,'FILL_BLANK','Вставь this/that или these/those (ближний — this/these, дальний — that/those).',$j${"items": [{"before": "(near)", "after": "cameras"}, {"before": "(far)", "after": "teddy bears."}, {"before": "(near)", "after": "an elephant"}, {"before": "(far)", "after": "a kangaroo."}, {"before": "(near)", "after": "clocks"}, {"before": "(far)", "after": "watches."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('ee8f1441-1fac-58d7-b1a2-8f324acb529e',$j${"items": [{"accept": ["these are", "these"]}, {"accept": ["those are", "those"]}, {"accept": ["this is", "this"]}, {"accept": ["that is", "that"]}, {"accept": ["these are", "these"]}, {"accept": ["those are", "those"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('e90f8a31-297b-5de5-a722-6ccf4aea288e','f1b4cec2-1f66-5cda-9d21-05ae124e25af',1,'FILL_BLANK','Напиши предложения во множественном числе.',$j${"items": [{"before": "This is a box. →", "after": ""}, {"before": "This is an umbrella. →", "after": ""}, {"before": "That is a mouse. →", "after": ""}, {"before": "This is a watch. →", "after": ""}]}$j$::jsonb,10);
