INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('600f2956-61f7-5e13-8b9d-5076ab19fffc','a0000000-0000-4000-8000-000000000001','Блок 7. There is / There are',7,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('3f62c64c-6aaf-5ec3-859d-b8d7c61e2e7b','600f2956-61f7-5e13-8b9d-5076ab19fffc','There is / There are',0,'LESSON',70,$j$[{"type": "examples", "items": ["Affirmative: There is a cat. / There's a cat. — There are two cats.", "Negative: There isn't a cat. — There aren't two cats.", "Interrogative: Is there a cat? — Are there two cats?"]}, {"type": "rule", "text": "We use there is to list things in the singular. We use there are for the plural (there are has no short form)."}, {"type": "rule", "text": "Short answers: Is there ...? — Yes, there is. / No, there isn't. Are there ...? — Yes, there are. / No, there aren't."}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('9eb89bdc-3e7e-50b8-a1b5-81ddccb833f3','3f62c64c-6aaf-5ec3-859d-b8d7c61e2e7b',0,'FILL_BLANK','Вставь there is/isn''t или there are/aren''t (описание спальни).',$j${"items": [{"before": "", "after": "a bed but"}, {"before": "a bed but", "after": "a carpet."}, {"before": "", "after": "a lamp but"}, {"before": "a lamp but", "after": "a bookcase."}, {"before": "", "after": "three pillows but"}, {"before": "three pillows but", "after": "cushions."}]}$j$::jsonb,10);
