INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('e569e837-ba0a-57b9-8789-965a9b11f787','2ffae8b7-b2c6-581d-96cc-80f22ff91a19',0,'FILL_BLANK','Вставь some или any.',$j${"items": [{"before": "Is there", "after": "pizza?"}, {"before": "There aren't", "after": "desks in the classroom."}, {"before": "Are there", "after": "pens?"}, {"before": "There isn't", "after": "ice cream in the fridge."}, {"before": "There is", "after": "milk in the fridge."}, {"before": "Can I have", "after": "orange juice?"}, {"before": "There are", "after": "pencils on the desk."}, {"before": "Are there", "after": "apples in the basket?"}]}$j$::jsonb,10);
