INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('0d52ae02-cb1c-561b-81d0-e6f6cccf13f2','f0089b3b-c2b6-51ac-a67c-a7ca0cb4ee0a','Can',0,'LESSON',70,$j$[{"type": "rule", "text": "We use can to express ability. I can play the guitar."}, {"type": "rule", "text": "Can is the same in all persons. The negative is cannot or can't."}, {"type": "examples", "items": ["Affirmative: I can walk. Negative: I can't walk. Interrogative: Can you walk? Short answers: Yes, I can. / No, I can't."]}]$j$::jsonb);
