INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('04fa86fb-c0f7-5788-8f89-271b77a10e1e','70b0be03-e6ca-59c0-9175-02f8c356a237','Possessive Case',0,'LESSON',70,$j$[{"type": "rule", "text": "We add 's to names and singular nouns (Sally's handbag). We add ' to plural nouns ending in -s (the girls' ball)."}, {"type": "rule", "text": "For things we usually use the preposition of (the legs of the table). We use whose to ask about possession."}]$j$::jsonb);
