INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('c2e49a47-89ba-5b51-9fa3-ba5f0244948a','04fa86fb-c0f7-5788-8f89-271b77a10e1e',1,'CHOOSE','Выбери who''s или whose (who''s = who is; whose = принадлежность).',$j${"items": [{"before": "A:", "after": "pen is this? B: It's Tom's.", "options": [{"id": "q2a", "label": "Who's"}, {"id": "q2b", "label": "Whose"}]}, {"before": "A:", "after": "he? B: He's my teacher.", "options": [{"id": "q3a", "label": "Whose"}, {"id": "q3b", "label": "Who's"}]}, {"before": "A:", "after": "notebooks are these? B: They're Nancy's.", "options": [{"id": "q4a", "label": "Who's"}, {"id": "q4b", "label": "Whose"}]}, {"before": "A:", "after": "Susan? B: She's my friend.", "options": [{"id": "q6a", "label": "Who's"}, {"id": "q6b", "label": "Whose"}]}]}$j$::jsonb,10);
