INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('f809729e-e39f-5f8d-88d8-4c98ae9304b8','a0000000-0000-4000-8000-000000000001','Блок 13. Present Simple',13,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('22541d30-51a8-5b47-acea-b29346bab8a1','f809729e-e39f-5f8d-88d8-4c98ae9304b8','Present Simple',0,'LESSON',70,$j$[{"type": "rule", "text": "We use the present simple for permanent states, repeated actions/habits and daily routines."}, {"type": "rule", "text": "Spelling (3rd person): add -s to most verbs; add -es after -ss, -sh, -ch, -x, -o; consonant + y drops -y and takes -ies; vowel + y takes -s."}, {"type": "rule", "text": "Negative: doesn't + verb (3rd person), don't + verb (others). Interrogative: does/do + subject + verb."}, {"type": "text", "text": "Time expressions: usually, often, every day/week, sometimes."}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('32c50de4-13b7-5a90-b091-1410d3e2c5d0','22541d30-51a8-5b47-acea-b29346bab8a1',0,'FILL_BLANK','Напиши форму третьего лица единственного числа.',$j${"items": [{"before": "I like – he", "after": ""}, {"before": "I do – he", "after": ""}, {"before": "I wash – he", "after": ""}, {"before": "I watch – he", "after": ""}, {"before": "I mix – he", "after": ""}, {"before": "I try – he", "after": ""}, {"before": "I go – he", "after": ""}, {"before": "I fly – he", "after": ""}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('32c50de4-13b7-5a90-b091-1410d3e2c5d0',$j${"items": [{"accept": ["likes"]}, {"accept": ["does"]}, {"accept": ["washes"]}, {"accept": ["watches"]}, {"accept": ["mixes"]}, {"accept": ["tries"]}, {"accept": ["goes"]}, {"accept": ["flies"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('9d725e84-c905-5d38-9fa3-96cde6b08458','22541d30-51a8-5b47-acea-b29346bab8a1',1,'FILL_BLANK','Раскрой глаголы в скобках в present simple.',$j${"items": [{"before": "He", "after": "his homework every evening. (do)"}, {"before": "She", "after": "at Newcastle School. (work)"}, {"before": "Joanne", "after": "her hair every day. (wash)"}, {"before": "The museum", "after": "at seven. (close)"}, {"before": "She", "after": "Science at university. (study)"}, {"before": "We", "after": "to the swimming pool at the weekend. (go)"}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('9d725e84-c905-5d38-9fa3-96cde6b08458',$j${"items": [{"accept": ["does"]}, {"accept": ["works"]}, {"accept": ["washes"]}, {"accept": ["closes"]}, {"accept": ["studies"]}, {"accept": ["go"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('1bd649d0-648a-5e20-8712-a090da61050c','22541d30-51a8-5b47-acea-b29346bab8a1',2,'FILL_BLANK','Вставь do, does, don''t или doesn''t.',$j${"items": [{"before": "Paul speaks French, but he", "after": "speak Russian."}, {"before": "Anna", "after": "like jazz but she likes hip hop."}, {"before": "'", "after": "he play the saxophone?'"}, {"before": "Where", "after": "you work?"}, {"before": "He", "after": "go to school on Sundays."}, {"before": "'", "after": "Karen use a computer at work?' 'Yes, she does.'"}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('1bd649d0-648a-5e20-8712-a090da61050c',$j${"items": [{"accept": ["doesn't"]}, {"accept": ["doesn't"]}, {"accept": ["Does"]}, {"accept": ["do"]}, {"accept": ["doesn't"]}, {"accept": ["Does"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('bbd9ceb6-4db7-50d5-a389-6274dd9bff26','22541d30-51a8-5b47-acea-b29346bab8a1',3,'MATCH_PAIRS','Соотнеси вопросы с ответами.',$j${"left": [{"id": "l1", "label": "What time does she get up?"}, {"id": "l2", "label": "How does she go to school?"}, {"id": "l3", "label": "Does she have breakfast every day?"}, {"id": "l4", "label": "What does she do in the afternoon?"}, {"id": "l5", "label": "When does she go to bed?"}], "right": [{"id": "r1", "label": "She goes to bed at 10:00."}, {"id": "r2", "label": "She walks to school."}, {"id": "r3", "label": "She gets up at 7:00."}, {"id": "r4", "label": "No, she doesn't."}, {"id": "r5", "label": "She does her homework."}]}$j$::jsonb,10);
