INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('b6629a9e-1d72-5119-acda-464bf25e745e','a29a6da9-a21a-5759-9872-add0150ddd8d','Prepositions of Time: at, on, in',0,'LESSON',70,$j$[{"type": "rule", "text": "We use at with times and holidays (at 6 o'clock, at the weekend, at night, at noon)."}, {"type": "rule", "text": "We use on with days and dates (on Sunday, on 17th April)."}, {"type": "rule", "text": "We use in with parts of the day, months, seasons, years and expressions (in the morning, in January, in summer, in 2006, in half an hour)."}]$j$::jsonb);
