INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('555e4c63-4551-5aa3-8ffb-1b3dab30a419','a0b78cd6-78a2-53fc-8f37-cdee8abca61e','Adverbs of Frequency',0,'LESSON',70,$j$[{"type": "rule", "text": "Adverbs of frequency tell us how often something happens: always (100%), usually, often, sometimes, never (0%)."}, {"type": "rule", "text": "They go before the main verb but after the verb to be."}, {"type": "examples", "items": ["She always has pizza for lunch.", "They are never late for work."]}]$j$::jsonb);
