INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('c099a105-f1b8-5d85-9f1a-6de4289fa4c1','868aadeb-8918-5944-a121-61b3a4877570','Question Words',0,'LESSON',70,$j$[{"type": "rule", "text": "Wh-questions start with who, what, where, when, why, how, etc. Structure: Question word + auxiliary + subject."}, {"type": "examples", "items": ["Who is your best friend? — Where do you live? — Why can't penguins fly? — How old is Tom? — How many oranges do you eat?"]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('f2177cd1-7989-5f4c-a31a-184aed5f7fba','c099a105-f1b8-5d85-9f1a-6de4289fa4c1',0,'FILL_BLANK','Вставь вопросительное слово (what, when, how, why, whose, where, who).',$j${"items": [{"before": "", "after": "is your sister? — She's fine."}, {"before": "", "after": "are those shoes? — They're Paul's."}, {"before": "", "after": "is your name? — Daniel."}, {"before": "", "after": "are Jane and Kate? — At school."}, {"before": "", "after": "is Ken's birthday? — In February."}, {"before": "", "after": "is that man? — He's my grandpa."}]}$j$::jsonb,10);
