INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('839c6938-c067-5804-b589-7e8e543153f6','c099a105-f1b8-5d85-9f1a-6de4289fa4c1',1,'FILL_BLANK','Вставь how much, how many, how old, how tall, how far, how often, how long или what time.',$j${"items": [{"before": "", "after": "pencils have you got?"}, {"before": "", "after": "does he go to school?"}, {"before": "", "after": "is the museum?"}, {"before": "", "after": "tea do you drink every day?"}, {"before": "", "after": "does Sally go to the cinema?"}, {"before": "", "after": "is your mother?"}, {"before": "", "after": "are the twins?"}]}$j$::jsonb,10);
