INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('337e3000-042e-5e9a-a202-30b04cb669e5','29f6ee5f-e5a5-56bc-8b7b-370c3ae8ec6b','Present Continuous',0,'LESSON',70,$j$[{"type": "rule", "text": "We form the present continuous with the verb 'to be' (am/is/are) and the main verb + -ing."}, {"type": "rule", "text": "We use it for actions happening now, at the moment of speaking."}, {"type": "text", "text": "Spelling: most verbs add -ing (walk – walking); -e drops and takes -ing (write – writing); vowel + consonant doubles the consonant (run – running); -ie becomes -ying (die – dying)."}, {"type": "text", "text": "Time expressions: now, at the moment, at present."}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('088ed795-3440-51ca-9ed6-fb411211ceec','337e3000-042e-5e9a-a202-30b04cb669e5',0,'SORT_COLUMNS','Распредели глаголы по колонкам согласно правилу -ing.',$j${"columns": [{"id": "c1", "label": "+ ing"}, {"id": "c2", "label": "-e + ing"}, {"id": "c3", "label": "double consonant + ing"}], "items": [{"id": "i1", "label": "talk"}, {"id": "i2", "label": "write"}, {"id": "i3", "label": "stop"}, {"id": "i4", "label": "go"}, {"id": "i5", "label": "swim"}, {"id": "i7", "label": "make"}, {"id": "i8", "label": "run"}, {"id": "i9", "label": "dance"}, {"id": "i11", "label": "eat"}, {"id": "i12", "label": "sit"}]}$j$::jsonb,10);
