INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('03b2e45c-c29e-5e1c-aae6-aab0aeced9e8','a0000000-0000-4000-8000-000000000001','Блок 18. Present Simple – Present Continuous',18,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('828adceb-90ad-5c3b-852d-34fb75792c38','03b2e45c-c29e-5e1c-aae6-aab0aeced9e8','Present Simple – Present Continuous',0,'LESSON',70,$j$[{"type": "rule", "text": "We use the present simple for daily routines, habits and permanent states."}, {"type": "rule", "text": "We use the present continuous for actions happening now."}, {"type": "rule", "text": "Non-Continuous Verbs (want, love, know, like) are not normally used in the continuous form."}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('d6ec7e7e-2997-5022-a97a-4e756c0ebc64','828adceb-90ad-5c3b-852d-34fb75792c38',0,'FILL_BLANK','Поставь глаголы в present simple или present continuous.',$j${"items": [{"before": "Where's Peter? — He", "after": "(study) for an exam right now."}, {"before": "I usually", "after": "(play) basketball on Tuesdays."}, {"before": "Oh, because it", "after": "(rain) outside."}, {"before": "What", "after": "(you/do) at the moment?"}, {"before": "I", "after": "(cook) dinner."}]}$j$::jsonb,10);
