INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('0d734114-1fdc-5940-bed2-941819f2bb4d','828adceb-90ad-5c3b-852d-34fb75792c38',1,'FILL_BLANK','Поставь глаголы в present simple или present continuous.',$j${"items": [{"before": "Steve", "after": "(wear) his new hat today."}, {"before": "The baby", "after": "(sleep) at the moment."}, {"before": "Karen sometimes", "after": "(wear) long skirts."}, {"before": "Mr Harris", "after": "(work) in a museum."}, {"before": "Please be quiet! I", "after": "(try) to do my homework."}, {"before": "I", "after": "(not/like) rainy days."}]}$j$::jsonb,10);
