INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('b4f5c836-03eb-5c0f-8382-7d768cf12ca8','a0000000-0000-4000-8000-000000000001','Блок 20. Past Simple (regular verbs)',20,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('5640d60d-0e29-51f0-9c65-df3717a8f20b','b4f5c836-03eb-5c0f-8382-7d768cf12ca8','Past Simple (regular verbs)',0,'LESSON',70,$j$[{"type": "rule", "text": "We form the past simple of regular verbs by adding -ed. Add -d after -e; consonant + y becomes -ied; a stressed vowel between two consonants doubles the last consonant + -ed (stop – stopped)."}, {"type": "rule", "text": "Questions: did + subject + base verb. Negations: didn't + base verb."}, {"type": "rule", "text": "We use the past simple for actions that started and finished in the past."}, {"type": "text", "text": "Time expressions: yesterday, last week/month/year, two days ago, in 1979."}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('3bbb67f2-e9d5-5a39-b958-5fb88b931ae0','5640d60d-0e29-51f0-9c65-df3717a8f20b',0,'FILL_BLANK','Напиши глаголы в past simple.',$j${"items": [{"before": "borrow →", "after": ""}, {"before": "carry →", "after": ""}, {"before": "close →", "after": ""}, {"before": "play →", "after": ""}, {"before": "jog →", "after": ""}, {"before": "live →", "after": ""}, {"before": "smile →", "after": ""}, {"before": "grab →", "after": ""}]}$j$::jsonb,10);
