INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('a7e80721-5ef3-5742-bd39-832859942760','5640d60d-0e29-51f0-9c65-df3717a8f20b',1,'FILL_BLANK','Раскрой скобки, поставив глаголы в past simple.',$j${"items": [{"before": "Last year, Kelly and Diane", "after": "(decide) to go to France."}, {"before": "They", "after": "(travel) by aeroplane to Paris"}, {"before": "and", "after": "(share) a room at a hotel."}, {"before": "They", "after": "(walk) all day in the city"}, {"before": "and", "after": "(visit) many museums."}, {"before": "They", "after": "(enjoy) their holiday a lot!"}]}$j$::jsonb,10);
