INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('d1fb7a23-8bf2-5643-849d-a7b35aab467b','5640d60d-0e29-51f0-9c65-df3717a8f20b',2,'MATCH_PAIRS','Соотнеси вопросы с ответами.',$j${"left": [{"id": "l1", "label": "Where did you live ten years ago?"}, {"id": "l2", "label": "Who did Tom and Sue visit last night?"}, {"id": "l3", "label": "What time did your mum cook dinner?"}, {"id": "l4", "label": "When did Ann start playing tennis?"}, {"id": "l7", "label": "What did Helen study yesterday?"}], "right": [{"id": "r1", "label": "In Ireland."}, {"id": "r2", "label": "Their friends."}, {"id": "r3", "label": "At 6 o'clock."}, {"id": "r4", "label": "When she was 8 years old."}, {"id": "r7", "label": "Chemistry."}]}$j$::jsonb,10);
