INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('d1a66d94-f4ae-5b71-96ed-6ef2bec02de9','a0000000-0000-4000-8000-000000000001','Блок 22. Countable / Uncountable Nouns',22,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('994fa5b4-18c2-5775-878f-b226712c86be','d1a66d94-f4ae-5b71-96ed-6ef2bec02de9','Countable / Uncountable Nouns',0,'LESSON',70,$j$[{"type": "rule", "text": "Countable nouns can be counted (one tomato – two tomatoes). Uncountable nouns cannot (some bread, some milk)."}, {"type": "rule", "text": "Uncountable nouns usually have only singular forms: food (bread, cheese, rice, sugar) and liquids (coffee, water, milk)."}, {"type": "text", "text": "Quantity units: a bottle of oil, a cup of tea, a glass of water, a bowl of rice, a slice of pizza, a loaf of bread, a kilo of meat, a piece of cake."}]$j$::jsonb);
