INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('6d86da5c-75c8-5de4-88f9-c4424893948f','d97ccc8b-874c-50b8-b6a2-1ed66adf62b7','Some/Any – How much/How many',0,'LESSON',70,$j$[{"type": "rule", "text": "We use some in affirmatives; any in negatives and questions. We use some in offers/requests."}, {"type": "rule", "text": "We use how much with uncountable nouns and how many with countable nouns."}, {"type": "examples", "items": ["How much milk do you want? — How many apples have you got?"]}]$j$::jsonb);
