INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('6b6adf38-63b0-597f-bcf7-76230eef46cf','d4b7658d-49b7-57f8-a99b-ced6d6e53568','A / An – The',0,'LESSON',70,$j$[{"type": "rule", "text": "We use a/an before singular countable nouns: 'a' before a consonant sound, 'an' before a vowel sound (a hat, an hour — h is silent)."}, {"type": "rule", "text": "We use a/an to say what somebody/something is or someone's job (This is a seal. He is a scientist.)."}, {"type": "rule", "text": "We don't use a/an with uncountable or plural nouns (use some instead)."}, {"type": "rule", "text": "We use 'the' with specific nouns, or when the noun is mentioned a second time (I can see a hat. The hat is brown.)."}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('69046e0b-27f4-563f-992d-2ec1fa054877','6b6adf38-63b0-597f-bcf7-76230eef46cf',0,'FILL_BLANK','Вставь a, an или the.',$j${"items": [{"before": "", "after": "skirt you bought is lovely."}, {"before": "Borders is", "after": "bookshop."}, {"before": "I want to buy", "after": "newspaper,"}, {"before": "but", "after": "newsagent's is closed."}, {"before": "Lisa's brother is", "after": "acrobat."}, {"before": "I can see", "after": "bicycle in the garden."}, {"before": "It is", "after": "old bicycle."}, {"before": "Neil Armstrong was", "after": "astronaut."}, {"before": "He was", "after": "first man to walk on the moon."}]}$j$::jsonb,10);
