INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('44570d44-5ec6-56be-83bd-8186a76f750e','d33761d8-1162-5f90-91ad-6b6459ecb4d9','Must – Mustn''t',0,'LESSON',70,$j$[{"type": "rule", "text": "We use must to describe obligation, duty or strong advice. We use mustn't to express prohibition."}, {"type": "examples", "items": ["You must listen to your teacher.", "You mustn't drive fast.", "You must wear a helmet when you ride a bicycle."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('8ff7b22f-f8d2-5c8d-b563-f1badeb5cb7f','44570d44-5ec6-56be-83bd-8186a76f750e',0,'FILL_BLANK','Вставь must или mustn''t.',$j${"items": [{"before": "You", "after": "do your homework every day."}, {"before": "You", "after": "be rude to your parents."}, {"before": "We", "after": "buy some flowers for the party."}, {"before": "You", "after": "drink too much coffee."}, {"before": "You", "after": "clean your teeth every day."}, {"before": "You", "after": "drive fast."}, {"before": "You", "after": "exercise three times a week."}, {"before": "You", "after": "eat too many sweets."}]}$j$::jsonb,10);
