INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('2583a6ef-da74-5a52-b3b4-baf0d7e7cfb2','a590501c-b60b-5eab-b3e4-23a15c321f7b','Be going to',0,'LESSON',70,$j$[{"type": "rule", "text": "We use 'be going to' to talk about future plans and intentions, and to make predictions based on what we can see."}, {"type": "examples", "items": ["She's going to have a picnic tomorrow. (plan)", "It's going to rain. There are dark clouds. (prediction)"]}, {"type": "text", "text": "Time expressions: tomorrow, this weekend, next Monday, next month."}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('8f169a2f-c619-5cac-854a-b88cdd4d1936','2583a6ef-da74-5a52-b3b4-baf0d7e7cfb2',0,'FILL_BLANK','Раскрой скобки, используя правильную форму be going to.',$j${"items": [{"before": "Lucy", "after": "(go) on a tour around Europe next summer."}, {"before": "Look at that man! He", "after": "(steal) that woman's bag!"}, {"before": "I", "after": "(walk) to work tomorrow."}, {"before": "Ken", "after": "(not/play) tennis this weekend because he's sick."}, {"before": "Chris and Rita", "after": "(visit) their parents next Thursday."}]}$j$::jsonb,10);
