INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('1e28dc11-5f68-5351-8910-013db2bca46d','9addd4da-dfad-5dff-8735-f8ed21520295','Imperative',0,'LESSON',70,$j$[{"type": "rule", "text": "We form the imperative with the base form of the verb without the subject."}, {"type": "rule", "text": "We form the negative imperative with don't + the base form."}, {"type": "examples", "items": ["Feed the dog, please!", "Don't close the door!", "Be quiet!"]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('464871d9-aa4e-5cc2-90fb-83335003c005','1e28dc11-5f68-5351-8910-013db2bca46d',0,'MATCH_PAIRS','Соотнеси команды с ситуациями.',$j${"left": [{"id": "l1", "label": "Get out!"}, {"id": "l2", "label": "Look over there!"}, {"id": "l3", "label": "Write on the board!"}, {"id": "l4", "label": "Be quiet!"}, {"id": "l5", "label": "Raise your hands!"}, {"id": "l6", "label": "Blow out the candles!"}], "right": [{"id": "r1", "label": "an angry man pointing at the exit"}, {"id": "r2", "label": "pointing into the distance"}, {"id": "r3", "label": "a teacher pointing at the board"}, {"id": "r4", "label": "a finger to the lips"}, {"id": "r5", "label": "students with arms up"}, {"id": "r6", "label": "a birthday cake with candles"}]}$j$::jsonb,10);
