INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('91b0448f-e2a0-56ba-b285-d743f13dfe8c','a0000000-0000-4000-8000-000000000001','Блок 28. Can – Can''t',28,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('2f7bb6f0-9616-5ee4-a9c9-cfaf5e10c678','91b0448f-e2a0-56ba-b285-d743f13dfe8c','Can – Can''t',0,'LESSON',70,$j$[{"type": "rule", "text": "We use can to talk about ability, to give permission and to show possibility. We use can't to refuse permission."}, {"type": "examples", "items": ["I can play the piano. (ability)", "You can borrow my car. (permission)", "You can't use my pencil. I need it. (refuse)"]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('6b2afefa-5cc9-5ec4-811e-24f580b584ef','2f7bb6f0-9616-5ee4-a9c9-cfaf5e10c678',0,'CHOOSE','Выбери правильное слово.',$j${"items": [{"before": "You", "after": "go to the cinema tonight, because you have to do your homework.", "options": [{"id": "1a", "label": "can"}, {"id": "1b", "label": "can't"}]}, {"before": "I", "after": "come and see you tomorrow if you like.", "options": [{"id": "2a", "label": "can't"}, {"id": "2b", "label": "can"}]}, {"before": "You", "after": "borrow my ruler. I don't need it.", "options": [{"id": "4a", "label": "can't"}, {"id": "4b", "label": "can"}]}, {"before": "They", "after": "walk on the grass. It's not allowed.", "options": [{"id": "6a", "label": "can't"}, {"id": "6b", "label": "can"}]}, {"before": "Helen", "after": "swim very well, but she's taking lessons.", "options": [{"id": "10a", "label": "can't"}, {"id": "10b", "label": "can"}]}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('6b2afefa-5cc9-5ec4-811e-24f580b584ef',$j${"items": [{"correctId": "1b"}, {"correctId": "2b"}, {"correctId": "4b"}, {"correctId": "6a"}, {"correctId": "10a"}]}$j$::jsonb,'');
